41	// explode into all combinations
42	const pairs = QUOTE_PREFIX_KINDS.flatMap((prefix) =>
43	  quoteKinds.map(([start, end]) => [prefix + start, end]),
44	);
45	
46	const regexes = pairs.map(
47	  ([start, end]) =>
48	    // mo.md( + any number of spaces + start + capture + any number of spaces + end)
49	    [
50	      start,
51	      new RegExp(`^mo\\.md\\(\\s*${start}(.*)${end}\\s*\\)$`, "s"),
52	    ] as const,
