55	/**
56	 * Language adapter for Markdown.
57	 */
58	export class MarkdownLanguageAdapter implements LanguageAdapter {
59	  readonly type = "markdown";
60	  readonly defaultCode = 'mo.md(r"""\n""")';
61	
62	  static fromMarkdown(markdown: string) {
63	    return `mo.md(r"""\n${markdown}\n""")`;
64	  }
65	
66	  lastQuotePrefix: QuotePrefixKind = "r";
67	
68	  transformIn(pythonCode: string): [string, number] {
69	    pythonCode = pythonCode.trim();
70	
71	    // empty string
72	    if (pythonCode === "") {
73	      this.lastQuotePrefix = "r";
74	      return ["", 0];
75	    }
76	
77	    for (const [start, regex] of regexes) {
78	      const match = pythonCode.match(regex);
79	      if (match) {
80	        const innerCode = match[1];
81	
82	        const [quotePrefix, quoteType] = splitQuotePrefix(start);
83	        // store the quote prefix for later when we transform out
84	        this.lastQuotePrefix = quotePrefix;
85	        const unescapedCode = innerCode.replaceAll(`\\${quoteType}`, quoteType);
86	
87	        const offset = pythonCode.indexOf(innerCode);
88	        // string-dedent expects the first and last line to be empty / contain only whitespace, so we pad with \n
89	        return [dedent(`\n${unescapedCode}\n`).trim(), offset];
90	      }
91	    }
92	
93	    // no match
94	    this.lastQuotePrefix = "r";
95	    return [pythonCode, 0];
96	  }
97	
98	  transformOut(code: string): [string, number] {
99	    // Get the quote type from the last transformIn
100	    const prefix = this.lastQuotePrefix;
101	
102	    // Empty string
103	    if (code === "") {
104	      // Need at least a space, otherwise the output will be 6 quotes
105	      code = " ";
106	    }
107	
108	    // We always transform back with triple quotes, as to avoid needing to
109	    // escape single quotes.
110	    const escapedCode = code.replaceAll('"""', String.raw`\"""`);
111	
112	    // If its one line and not bounded by quotes, write it as single line
113	    const isOneLine = !code.includes("\n");
114	    const boundedByQuote = code.startsWith('"') || code.endsWith('"');
115	    if (isOneLine && !boundedByQuote) {
116	      const start = `mo.md(${prefix}"""`;
117	      const end = `""")`;
118	      return [start + escapedCode + end, start.length];
119	    }
120	
121	    // Multiline code
122	    const start = `mo.md(\n    ${prefix}"""\n`;
123	    const end = `\n    """\n)`;
124	    return [start + indentOneTab(escapedCode) + end, start.length + 1];
125	  }
126	
127	  isSupported(pythonCode: string): boolean {
128	    if (pythonCode.trim() === "") {
129	      return true;
130	    }
131	
132	    if (pythonCode.trim() === "mo.md()") {
133	      return true;
134	    }
135	
136	    // Handle mo.md("foo"), mo.plain_text("bar") in the same line
137	    // If it starts with mo.md, but we have more than one function call, return false
138	    if (pythonCode.trim().startsWith("mo.md(")) {
139	      const tree = pythonLanguage.parser.parse(pythonCode);
140	      let functionCallCount = 0;
141	
142	      // Parse the code using Lezer to check for multiple function calls
143	      tree.iterate({
144	        enter: (node) => {
145	          if (node.name === "CallExpression") {
146	            functionCallCount++;
147	            if (functionCallCount > 1) {
148	              return false; // Stop iterating if we've found more than one function call
149	            }
150	          }
151	        },
152	      });
153	
154	      // If the function call count is greater than 1, we don't want to show "view as markdown"
155	      if (functionCallCount > 1) {
156	        return false;
157	      }
158	    }
159	
160	    return regexes.some(([, regex]) => regex.test(pythonCode));
161	  }
