8	  DataColumnPreview,
9	  OperationMessageData,
10	} from "../kernel/messages";
11	import { previewDatasetColumn } from "../network/requests";
12	
13	function initialState(): DatasetsState {
14	  return {
15	    tables: [],
16	    expandedTables: new Set(),
17	    expandedColumns: new Set(),
18	    columnsPreviews: new Map(),
19	  };
20	}
21	
22	const {
23	  reducer,
24	  createActions,
25	  valueAtom: datasetsAtom,
26	  useActions,
27	} = createReducerAndAtoms(initialState, {
28	  addDatasets: (state, datasets: OperationMessageData<"datasets">) => {
29	    // Quietly in the background make requests to get the previews for
30	    // opened columns, in the new tables
31	    for (const table of datasets.tables) {
32	      for (const column of table.columns) {
33	        const tableColumn = `${table.name}:${column.name}` as const;
34	        if (state.expandedColumns.has(tableColumn)) {
35	          // Fire and forget
36	          void previewDatasetColumn({
37	            tableName: table.name,
38	            columnName: column.name,
39	            source: table.source,
40	            sourceType: table.source_type,
41	          });
42	        }
43	      }
44	    }
45	
46	    // Prev tables
47	    let prevTables = state.tables;
48	    if (datasets.clear_channel) {
49	      prevTables = prevTables.filter((table) => {
50	        return table.source !== datasets.clear_channel;
51	      });
52	    }
53	
54	    // Put new tables at the top
55	    const newTables = [...datasets.tables, ...prevTables];
56	
57	    // Dedupe by name and source
58	    const seen = new Set();
59	    const dedupedTables = newTables.filter((table) => {
