import type { Extension } from "@codemirror/state";
import {
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { pythonLanguage } from "@codemirror/lang-python";
import { store } from "@/core/state/jotai";
import { variablesAtom } from "@/core/variables/state";

// Node names for the embedded Python interpolation block (e.g. `{variable}`)
const PYTHON = "Python";
const PYTHON_MARK = "PythonMark";

const CHAR_CODES = {
  OPEN_BRACE: 123, // {
  CLOSE_BRACE: 125, // }
};

// Delimiter must be defined as a constant because it is used in object match
// tests when resolving the parsed node.
const PYTHON_DELIMITER: DelimiterType = {
  mark: PYTHON_MARK,
  resolve: PYTHON,
};

/**
 * Define an embedded Python parser for template-style `{ ... }` interpolation
 * blocks inside Markdown.
 *
 * @param pythonParser CodeMirror {@link Parser} for Python
 * @param isActivated Whether the embedded Python parsing is currently enabled
 * @returns Markdown extension
 */
export function parsePython(
  pythonParser: Parser,
  isActivated: () => boolean,
): MarkdownConfig {
  const defineNodes: NodeSpec[] = [
    { name: PYTHON, style: tags.emphasis },
    { name: PYTHON_MARK, style: tags.processingInstruction },
  ];

  return {
    defineNodes,
    parseInline: [
      {
        name: PYTHON,
        parse(cx: InlineContext, next: number, pos: number): number {
          // Do not parse when the embedded Python is disabled.
          if (!isActivated()) {
            return -1;
          }

          const isOpenBrace = next === CHAR_CODES.OPEN_BRACE;
          const isCloseBrace = next === CHAR_CODES.CLOSE_BRACE;

          // Only handle single curly braces.
          if (!isOpenBrace && !isCloseBrace) {
            return -1;
          }

          // Ignore escaped double braces (`{{` or `}}`), which are literal
          // braces rather than an interpolation block.
          if (isOpenBrace && cx.char(pos + 1) === CHAR_CODES.OPEN_BRACE) {
            return -1;
          }
          if (isCloseBrace && cx.char(pos - 1) === CHAR_CODES.CLOSE_BRACE) {
            return -1;
          }

          return cx.addDelimiter(
            PYTHON_DELIMITER,
            pos,
            pos + 1,
            isOpenBrace,
            isCloseBrace,
          );
        },
      },
    ],
    wrap: parseMixed((node) => {
      if (node.type.name !== PYTHON) {
        return null;
      }

      // Remove the surrounding braces from the Python overlay.
      const from = node.from + 1;
      const to = node.to - 1;

      // Ensure valid ranges
      if (from >= to || from < 0 || to < 0) {
        return null;
      }

      return {
        parser: pythonParser,
        overlay: [{ from, to }],
      };
    }),
  };
}

/**
 * Build the list of completions for the notebook's variables.
 */
function getVariableCompletions(): Completion[] {
  const variables = store.get(variablesAtom);
  return Object.values(variables).map(
    (variable): Completion => ({
      label: variable.name,
      displayLabel: variable.name,
      type: "variable",
      detail: variable.dataType ?? undefined,
      boost: 1,
    }),
  );
}

/**
 * Provide variable-name completions inside embedded Python regions.
 *
 * This is registered as Python language data so it only fires when the cursor
 * is inside a region that is parsed as Python (e.g. an interpolation block).
 */
export function embeddedPythonCompletions(
  isActivated: () => boolean,
): Extension {
  return [
    pythonLanguage.data.of({
      autocomplete: (context: CompletionContext): CompletionResult | null => {
        const word = context.matchBefore(/\w*/);
        if (!isActivated() || !context.explicit || !word) {
          return null;
        }

        return {
          from: word.from,
          options: getVariableCompletions(),
          validFor: /^\w*$/,
        };
      },
    }),
  ];
}

/**
 * A completion source for variable names inside template-style single-brace
 * interpolation blocks (e.g. `{variable}`).
 *
 * Unlike {@link embeddedPythonCompletions}, this does not rely on the document
 * being parsed as Python; it inspects the text before the cursor to determine
 * whether we are inside a valid single-brace block.
 */
export function variableCompletionSource(
  context: CompletionContext,
): CompletionResult | null {
  const textBefore = context.state.sliceDoc(0, context.pos);

  // Must have an open brace before the cursor.
  const lastOpenBrace = textBefore.lastIndexOf("{");
  if (lastOpenBrace === -1) {
    return null;
  }

  // A closing brace after the last open brace means the block is already
  // closed and we are no longer inside an interpolation block.
  const lastCloseBrace = textBefore.lastIndexOf("}");
  if (lastCloseBrace > lastOpenBrace) {
    return null;
  }

  // Ignore escaped double-brace sequences (`{{`), which are literal braces.
  const isDoubleBrace =
    textBefore[lastOpenBrace - 1] === "{" ||
    textBefore[lastOpenBrace + 1] === "{";
  if (isDoubleBrace) {
    return null;
  }

  const word = context.matchBefore(/\w*/);
  if (!word) {
    return null;
  }

  return {
    from: word.from,
    options: getVariableCompletions(),
    validFor: /^\w*$/,
  };
}
